//! Byte-level view of the C memory of the `Lxr` globals (non-C helper, group P3).
//!
//! Generated by the P3 layout generator from `ptype /o` of the reference ELF (`lxr_v1.7_gcc11.3.elf`):
//! every C struct used by an `Lxr` field gets `CMem`, which reads and writes the bytes of its C
//! representation (little endian; padding reads 0 and ignores writes). `Lxr::global_get_byte` /
//! `global_set_byte` map a firmware RAM address to the field that holds it. Used by the `cptr_*`
//! resolvers (pointer targets, including reinterpreting reads such as an `f32` load from an `f64`
//! field), by out-of-bounds stores the firmware performs, and by the differential tests to load and
//! compare the whole engine state against emulator memory.
#![allow(non_snake_case, unused_variables, clippy::all)]
use crate::prelude::*;
use crate::memmap::*;

/// C memory representation of a type.
pub trait CMem {
    /// `sizeof` in C.
    const SIZE: u32;
    fn get_byte(&self, off: u32) -> u8;
    fn set_byte(&mut self, off: u32, v: u8);
}

macro_rules! prim {
    ($($t:ty),*) => {$(
        impl CMem for $t {
            const SIZE: u32 = core::mem::size_of::<$t>() as u32;
            #[inline]
            fn get_byte(&self, off: u32) -> u8 { self.to_le_bytes()[off as usize] }
            #[inline]
            fn set_byte(&mut self, off: u32, v: u8) {
                let mut b = self.to_le_bytes();
                b[off as usize] = v;
                *self = <$t>::from_le_bytes(b);
            }
        }
    )*};
}
prim!(u8, i8, u16, i16, u32, i32, u64, i64, f32, f64);

impl<T: CMem, const N: usize> CMem for [T; N] {
    const SIZE: u32 = T::SIZE * N as u32;
    #[inline]
    fn get_byte(&self, off: u32) -> u8 { self[(off / T::SIZE) as usize].get_byte(off % T::SIZE) }
    #[inline]
    fn set_byte(&mut self, off: u32, v: u8) { self[(off / T::SIZE) as usize].set_byte(off % T::SIZE, v) }
}

impl<T: CMem> CMem for Box<T> {
    const SIZE: u32 = T::SIZE;
    #[inline]
    fn get_byte(&self, off: u32) -> u8 { (**self).get_byte(off) }
    #[inline]
    fn set_byte(&mut self, off: u32, v: u8) { (**self).set_byte(off, v) }
}

impl CMem for ptrValue {
    const SIZE: u32 = 4;
    fn get_byte(&self, off: u32) -> u8 { self.itg.get_byte(off) }
    fn set_byte(&mut self, off: u32, v: u8) { self.itg.set_byte(off, v) }
}
impl CMem for seq_rndValue_t {
    const SIZE: u32 = 3;
    fn get_byte(&self, off: u32) -> u8 { [self.prev, self.current, self.next][off as usize] }
    fn set_byte(&mut self, off: u32, v: u8) {
        match off { 0 => self.prev = v, 1 => self.current = v, _ => self.next = v }
    }
}
