impl CMem for AutomationNode {
    const SIZE: u32 = 2;
    fn get_byte(&self, off: u32) -> u8 {
        match off {
            0..=1 => self.destination.get_byte(off - 0),
            _ => 0,
        }
    }
    fn set_byte(&mut self, off: u32, v: u8) {
        match off {
            0..=1 => self.destination.set_byte(off - 0, v),
            _ => {}
        }
    }
}

